pub fn math_add(a:i128,b:i128)->i128{a.checked_add(b).unwrap_or_else(||violation("arithmetic","validation","mathematical integer overflow"))}
pub fn math_sub(a:i128,b:i128)->i128{a.checked_sub(b).unwrap_or_else(||violation("arithmetic","validation","mathematical integer overflow"))}
pub fn math_mul(a:i128,b:i128)->i128{a.checked_mul(b).unwrap_or_else(||violation("arithmetic","validation","mathematical integer overflow"))}
pub fn math_neg(a:i128)->i128{a.checked_neg().unwrap_or_else(||violation("arithmetic","validation","mathematical integer overflow"))}
pub fn math_div(a:i128,b:i128)->i128{a.checked_div_euclid(b).unwrap_or_else(||violation("arithmetic","validation","invalid division"))}
pub fn math_rem(a:i128,b:i128)->i128{a.checked_rem_euclid(b).unwrap_or_else(||violation("arithmetic","validation","invalid remainder"))}
pub fn white_space(c:char)->bool{matches!(c,'\u{0009}'..='\u{000D}'|'\u{0020}'|'\u{0085}'|'\u{00A0}'|'\u{1680}'|'\u{2000}'..='\u{200A}'|'\u{2028}'|'\u{2029}'|'\u{202F}'|'\u{205F}'|'\u{3000}')}
pub fn unique_by<T,K:PartialEq>(values:&[T],key:impl Fn(&T)->&K)->bool{values.iter().enumerate().all(|(i,v)|values[..i].iter().all(|p|key(p)!=key(v)))}
pub fn permutation_by<T,K:PartialEq>(a:&[T],b:&[T],key:impl Fn(&T)->&K)->bool{a.len()==b.len()&&a.iter().all(|v|a.iter().filter(|x|key(x)==key(v)).count()==b.iter().filter(|x|key(x)==key(v)).count())}
pub fn unknown_dependency_by<T,K:PartialEq>(values:&[T],key:impl Fn(&T)->&K,deps:impl Fn(&T)->&Vec<K>)->bool{values.iter().any(|v|deps(v).iter().any(|d|!values.iter().any(|x|key(x)==d)))}
pub fn self_dependency_by<T,K:PartialEq>(values:&[T],key:impl Fn(&T)->&K,deps:impl Fn(&T)->&Vec<K>)->bool{values.iter().any(|v|deps(v).contains(key(v)))}
pub fn cyclic_by<T,K:PartialEq>(values:&[T],key:impl Fn(&T)->&K,deps:impl Fn(&T)->&Vec<K>)->bool{
 fn visit<T,K:PartialEq>(i:usize,v:&[T],key:&impl Fn(&T)->&K,deps:&impl Fn(&T)->&Vec<K>,marks:&mut[u8])->bool{if marks[i]==1{return true}if marks[i]==2{return false}marks[i]=1;for d in deps(&v[i]){if let Some(j)=v.iter().position(|x|key(x)==d){if visit(j,v,key,deps,marks){return true}}}marks[i]=2;false}
 let mut marks=vec![0;values.len()];(0..values.len()).any(|i|visit(i,values,&key,&deps,&mut marks))
}
pub fn dependency_ordered_by<T,K:PartialEq>(input:&[T],output:&[T],key:impl Fn(&T)->&K,deps:impl Fn(&T)->&Vec<K>)->bool{permutation_by(input,output,&key)&&output.iter().enumerate().all(|(i,v)|deps(v).iter().all(|d|output[..i].iter().any(|x|key(x)==d)))}

