// Compiler-only evidence. Authored implementation audits deny these identifiers.
#[derive(Clone,Debug)]
pub struct PredicateObservation{pub symbol:String,pub clause:String,pub phase:String,pub passed:bool}
thread_local!{static OBSERVER:std::cell::RefCell<Option<Vec<PredicateObservation>>>=const{std::cell::RefCell::new(None)};static VALIDATION:std::cell::Cell<bool>=const{std::cell::Cell::new(false)};}
#[doc(hidden)]
pub fn __cott_observe_begin(){OBSERVER.with(|o|*o.borrow_mut()=Some(Vec::new()));VALIDATION.with(|v|v.set(true));}
#[doc(hidden)]
pub fn __cott_observe_end()->Vec<PredicateObservation>{VALIDATION.with(|v|v.set(false));OBSERVER.with(|o|o.borrow_mut().take().unwrap_or_default())}
#[doc(hidden)]
pub fn __cott_validation_enabled(boundary:bool)->bool{boundary||ASYNC_OBSERVER.try_with(|_|true).unwrap_or(false)||VALIDATION.with(|v|v.get())}
#[doc(hidden)]
pub fn __cott_check(symbol:&str,phase:&str,clause:&str,passed:bool){let event=||PredicateObservation{symbol:symbol.into(),clause:clause.into(),phase:phase.into(),passed};if ASYNC_OBSERVER.try_with(|o|o.lock().expect("observation sink").push(event())).is_err(){OBSERVER.with(|o|{if let Some(events)=o.borrow_mut().as_mut(){events.push(event())}});}if !passed{violation(symbol,phase,clause)}}
tokio::task_local!{static ASYNC_OBSERVER:Arc<std::sync::Mutex<Vec<PredicateObservation>>>;}
#[doc(hidden)]
pub async fn __cott_observe_async<F:Future>(future:F)->(Result<F::Output,Box<dyn std::any::Any+Send>>,Vec<PredicateObservation>){
 let sink=Arc::new(std::sync::Mutex::new(Vec::new()));
 let result=ASYNC_OBSERVER.scope(sink.clone(),async move {
  let mut future=std::pin::pin!(future);
  std::future::poll_fn(|cx|match std::panic::catch_unwind(std::panic::AssertUnwindSafe(||future.as_mut().poll(cx))){Ok(std::task::Poll::Ready(value))=>std::task::Poll::Ready(Ok(value)),Ok(std::task::Poll::Pending)=>std::task::Poll::Pending,Err(error)=>std::task::Poll::Ready(Err(error))}).await
 }).await;
 let events=std::mem::take(&mut *sink.lock().expect("observation sink"));(result,events)
}
